 C. Entanglementbased Memory (Összefonódás)

Hebbi tanulás hardver szinten:
zig
pub const BlockIdSet = std.AutoHashMap(BlockID, void);

pub fn entangleBlocks(self: *ChaosCore, block_a: BlockID, block_b: BlockID) !void {
    const entangled_set = try self.entanglement_graph.getOrPut(block_a);
    if (!entangled_set.found_existing) {
        entangled_set.value_ptr.* = BlockIdSet.init(self.allocator);
    }
    try entangled_set.value_ptr.put(block_b, {});

    const reverse_set = try self.entanglement_graph.getOrPut(block_b);
    if (!reverse_set.found_existing) {
        reverse_set.value_ptr.* = BlockIdSet.init(self.allocator);
    }
    try reverse_set.value_ptr.put(block_a, {});
}


Önszerveződés:
zig
pub fn selfOrganize(self: *ChaosCore) !void {
    var it = self.entanglement_graph.iterator();
    while (it.next()) |entry| {
        const block_id = entry.key_ptr.*;
        const entangled_blocks = entry.value_ptr.*;

        var entangled_count: usize = 0;
        var eit = entangled_blocks.keyIterator();
        while (eit.next()) |entangled_id| {
            entangled_count += 1;
        }

        if (entangled_count > 3) {
            try self.optimizeDataPlacement(block_id, entangled_blocks);
        }
    }
}

fn optimizeDataPlacement(self: *ChaosCore, anchor: BlockID, related: BlockIdSet) !void {
    const target_core = self.findBestCoreForCluster(related);
    try self.migrateBlock(anchor, target_core);

    var it = related.keyIterator();
    while (it.next()) |block_id| {
        try self.migrateBlock(block_id.*, target_core);
    }
}


