 A. Tensor Műveletek (core/tensor.zig  68KB)

 Alapstruktúra
zig
pub const Tensor = struct {
    data: []f32,
    shape: []const usize,
    strides: []const usize,
    allocator: Allocator,
    refcount: ?*usize,

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor
    pub fn deinit(self: *Tensor) void
    pub fn clone(self: *const Tensor) !Tensor
};


CopyonWrite (COW):
zig
pub fn cow(self: *Tensor) !void {
    if (self.refcount) |rc| {
        if (rc.* > 1) {
            const new_data = try self.allocator.alloc(f32, self.data.len);
            @memcpy(new_data, self.data);
            rc.* -= 1;
            self.data = new_data;
            self.refcount = try self.allocator.create(usize);
            self.refcount.?.* = 1;
        }
    }
}


Előny: Memória hatékony klónozás (csak másolás ha módosítás)[github:kollarsandor/dontyoujuststop].

 Matrix Szorzás (Tiled)
zig
pub fn matmul(a: *const Tensor, b: *const Tensor, allocator: Allocator) !Tensor {
    const M = a.shape[0];
    const K = a.shape[1];
    const N = b.shape[1];

    var result = try Tensor.init(allocator, &.{M, N});

    const TILE_SIZE = 32;
    var i: usize = 0;
    while (i < M) : (i += TILE_SIZE) {
        var j: usize = 0;
        while (j < N) : (j += TILE_SIZE) {
            var k: usize = 0;
            while (k < K) : (k += TILE_SIZE) {
                try matmul_tile(a, b, &result, i, j, k, TILE_SIZE);
            }
        }
    }

    return result;
}

fn matmul_tile(a: *const Tensor, b: *const Tensor, c: *Tensor, 
               i_start: usize, j_start: usize, k_start: usize, 
               tile_size: usize) !void {
    const i_end = @min(i_start + tile_size, a.shape[0]);
    const j_end = @min(j_start + tile_size, b.shape[1]);
    const k_end = @min(k_start + tile_size, a.shape[1]);

    var i = i_start;
    while (i < i_end) : (i += 1) {
        var j = j_start;
        while (j < j_end) : (j += 1) {
            var sum: f32 = 0.0;
            var k = k_start;
            while (k < k_end) : (k += 1) {
                sum += a.data[i * a.strides[0] + k] * 
                       b.data[k * b.strides[0] + j];
            }
            c.data[i * c.strides[0] + j] += sum;
        }
    }
}


Cache optimalizálás: 32x32 tileok (L1 cache barát)[github:kollarsandor/dontyoujuststop].

 QR Faktorizáció (Householder)
zig
pub fn qr(a: *const Tensor, allocator: Allocator) !struct { Q: Tensor, R: Tensor } {
    const m = a.shape[0];
    const n = a.shape[1];

    var Q = try Tensor.eye(allocator, m);
    var R = try a.clone();

    var k: usize = 0;
    while (k < @min(m - 1, n)) : (k += 1) {
        var x = try R.slice(&.{k, k}, &.{m, k + 1});
        defer x.deinit();

        const alpha = try x.norm2();
        const sign: f32 = if (x.data[0] >= 0) 1.0 else -1.0;

        var v = try x.clone();
        defer v.deinit();
        v.data[0] += sign * alpha;

        const v_norm = try v.norm2();
        try v.scale(1.0 / v_norm);

        var H = try householderMatrix(&v, m, allocator);
        defer H.deinit();

        var temp_R = try H.matmul(&R);
        R.deinit();
        R = temp_R;

        var temp_Q = try Q.matmul(&H);
        Q.deinit();
        Q = temp_Q;
    }

    return .{ .Q = Q, .R = R };
}


Householder reflexió: Numerikusan stabil QR dekompozíció (Riesz Frigyes tisztelgés  funkcionálanalízis)[github:kollarsandor/dontyoujuststop].

 SVD (Singular Value Decomposition)
zig
pub fn svd(a: *const Tensor, allocator: Allocator) !struct { U: Tensor, S: Tensor, Vt: Tensor } {
    const m = a.shape[0];
    const n = a.shape[1];

    var ATA = try a.transpose().matmul(a);
    defer ATA.deinit();

    var V_eigvecs = try allocator.alloc(Tensor, n);
    defer {
        for (V_eigvecs) |*v| v.deinit();
        allocator.free(V_eigvecs);
    }
    var S_vals = try allocator.alloc(f32, n);
    defer allocator.free(S_vals);

    try powerIteration(&ATA, V_eigvecs, S_vals);

    var U = try Tensor.init(allocator, &.{m, n});
    for (0..n) |i| {
        const sigma = std.math.sqrt(S_vals[i]);
        var av = try a.matmul(&V_eigvecs[i]);
        defer av.deinit();
        try av.scale(1.0 / sigma);
        @memcpy(U.data[i * m .. (i + 1) * m], av.data);
    }

    var S = try Tensor.zeros(allocator, &.{n, n});
    for (0..n) |i| {
        S.data[i * n + i] = std.math.sqrt(S_vals[i]);
    }

    var Vt = try Tensor.init(allocator, &.{n, n});
    for (0..n) |i| {
        @memcpy(Vt.data[i * n .. (i + 1) * n], V_eigvecs[i].data);
    }

    return .{ .U = U, .S = S, .Vt = Vt };
}


Power iteration: Iteratív sajátérték keresés (spektrálelmélet  Riesz)[github:kollarsandor/dontyoujuststop].

 Cholesky Faktorizáció
zig
pub fn cholesky(a: *const Tensor, allocator: Allocator) !Tensor {
    const n = a.shape[0];
    var L = try Tensor.zeros(allocator, &.{n, n});

    var i: usize = 0;
    while (i < n) : (i += 1) {
        var j: usize = 0;
        while (j <= i) : (j += 1) {
            var sum: f32 = 0.0;
            var k: usize = 0;
            while (k < j) : (k += 1) {
                sum += L.data[i * n + k] * L.data[j * n + k];
            }

            if (i == j) {
                const val = a.data[i * n + i] - sum;
                if (val <= 0) return error.NotPositiveDefinite;
                L.data[i * n + j] = std.math.sqrt(val);
            } else {
                L.data[i * n + j] = (a.data[i * n + j] - sum) / L.data[j * n + j];
            }
        }
    }

    return L;
}


Pozitív definit mátrixokra: Gyors inverz számítás (Fisherinformációs mátrix kezelés)[github:kollarsandor/dontyoujuststop].

 B. RSF Processor (processor/rsf.zig  18KB)

Filozófia: Transformer alternatíva, Relational State Fields architektúra (Riesz Frigyes tisztelgés)[github:kollarsandor/dontyoujuststop].

 RSF Struktúra
zig
pub const RSFLayer = struct {
    s_weight: Tensor,
    t_weight: Tensor,
    s_bias: Tensor,
    t_bias: Tensor,
    dim: usize,

    pub fn init(allocator: Allocator, dim: usize) !RSFLayer
    pub fn deinit(self: *RSFLayer) void
};

pub const RSF = struct {
    layers: []RSFLayer,
    num_layers: usize,
    dim: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dim: usize, num_layers: usize) !RSF
    pub fn deinit(self: *RSF) void
    pub fn forward(self: *RSF, input: *Tensor) !void
    pub fn inverse(self: *RSF, output: *Tensor) !void
};


 Forward Pass (Spectral + Temporal)
zig
pub fn forward(self: *RSF, input: *Tensor) !void {
    if (input.shape.len != 2) return error.InvalidTensorShape;
    if (input.shape[1] != self.dim * 2) return error.DimensionMismatch;

    const batch = input.shape[0];
    const half_dim = self.dim;

    for (self.layers) |*layer| {
        var s_part = try input.slice(&.{0, 0}, &.{batch, half_dim});
        defer s_part.deinit();

        var t_part = try input.slice(&.{0, half_dim}, &.{batch, self.dim * 2});
        defer t_part.deinit();

        var s_transformed = try s_part.matmul(&layer.s_weight);
        defer s_transformed.deinit();
        try s_transformed.add(&layer.s_bias);
        try s_transformed.apply(silu);

        var t_transformed = try t_part.matmul(&layer.t_weight);
        defer t_transformed.deinit();
        try t_transformed.add(&layer.t_bias);
        try t_transformed.apply(tanh);

        @memcpy(input.data[0..batch * half_dim], s_transformed.data);
        @memcpy(input.data[batch * half_dim..], t_transformed.data);

        try relationalFusion(input, half_dim);
    }
}


SiLU aktiváció: f(x) = x * sigmoid(x) (smooth, differenciálható)[github:kollarsandor/dontyoujuststop].

Tanh aktiváció: Bounded output (1, 1) range

Relational Fusion:
zig
fn relationalFusion(tensor: *Tensor, dim: usize) !void {
    const batch = tensor.shape[0];

    var i: usize = 0;
    while (i < batch) : (i += 1) {
        var j: usize = 0;
        while (j < dim) : (j += 1) {
            const s_val = tensor.data[i * dim * 2 + j];
            const t_val = tensor.data[i * dim * 2 + dim + j];

            const fused = (s_val + t_val) * 0.5 + (s_val - t_val) * 0.3;

            tensor.data[i * dim * 2 + j] = fused;
            tensor.data[i * dim * 2 + dim + j] = (s_val + t_val) * 0.7;
        }
    }
}


Értelmezés: Spectral (frekvencia) és Temporal (idő) terek fúziója (funkcionálanalízis)[github:kollarsandor/dontyoujuststop].

 Inverse (Bijektív leképezés)
zig
pub fn inverse(self: *RSF, output: *Tensor) !void {
    if (output.shape.len != 2) return error.InvalidTensorShape;
    if (output.shape[1] != self.dim * 2) return error.DimensionMismatch;

    const batch = output.shape[0];
    const half_dim = self.dim;

    var layer_idx: usize = self.num_layers;
    while (layer_idx > 0) {
        layer_idx -= 1;
        const layer = &self.layers[layer_idx];

        try relationalDefusion(output, half_dim);

        var s_part = try output.slice(&.{0, 0}, &.{batch, half_dim});
        defer s_part.deinit();

        var t_part = try output.slice(&.{0, half_dim}, &.{batch, self.dim * 2});
        defer t_part.deinit();

        try s_part.apply(silu_inverse);
        try s_part.sub(&layer.s_bias);
        var s_inv = try s_part.matmul(&layer.s_weight.inverse());
        defer s_inv.deinit();

        try t_part.apply(tanh_inverse);
        try t_part.sub(&layer.t_bias);
        var t_inv = try t_part.matmul(&layer.t_weight.inverse());
        defer t_inv.deinit();

        @memcpy(output.data[0..batch * half_dim], s_inv.data);
        @memcpy(output.data[batch * half_dim..], t_inv.data);
    }
}


AGI kulcs: Kauzális visszakövetés (OkOkozati láncolat visszafejtés)[github:kollarsandor/dontyoujuststop].

 C. SFD Optimizer (optimizer/sfd.zig  21KB)

Filozófia: Spectral Fisher Descent  Natural Gradient közelítés (Wigner Jenő szimmetriaőrzés)[github:kollarsandor/dontyoujuststop].

 SFD Struktúra
zig
pub const SFD = struct {
    m: []f32,
    v: []f32,
    fisher_diag: []f32,
    step_count: usize,
    param_size: usize,
    allocator: Allocator,

    beta1: f32 = 0.9,
    beta2: f32 = 0.999,
    epsilon: f32 = 1e-8,
    fisher_decay: f32 = 0.95,

    pub fn init(allocator: Allocator, param_size: usize) !SFD
    pub fn deinit(self: *SFD) void
    pub fn update(self: *SFD, gradients: *Tensor, params: *Tensor, lr: f32) !void
    pub fn saveState(self: *const SFD, path: []const u8) !void
