 Morfológiai Elemzés
zig
const MorphemeType = enum {
    Prefix,
    Stem,
    Suffix,
    Standalone,
};

const Morpheme = struct {
    text: []const u8,
    type: MorphemeType,
    token_id: u32,
};

fn analyzeMorphology(self: *MGT, word: []const u8, allocator: Allocator) ![]Morpheme {
    var morphemes = std.ArrayList(Morpheme).init(allocator);

    const prefixes = [_][]const u8{ "meg", "el", "fel", "le", "ki", "be", "át" };
    const suffixes = [_][]const u8{ "nak", "nek", "ban", "ben", "hoz", "hez", "tól", "től" };

    var remaining = word;

    for (prefixes) |prefix| {
        if (std.mem.startsWith(u8, remaining, prefix)) {
            const token_id = self.token_to_id.get(prefix) orelse self.next_id;
            try morphemes.append(.{
                .text = prefix,
                .type = .Prefix,
                .token_id = token_id,
            });
            remaining = remaining[prefix.len..];
            break;
        }
    }

    var found_suffix = false;
    for (suffixes) |suffix| {
        if (std.mem.endsWith(u8, remaining, suffix)) {
            const stem_len = remaining.len - suffix.len;
            const stem = remaining[0..stem_len];

            const stem_id = self.token_to_id.get(stem) orelse self.next_id;
            try morphemes.append(.{
                .text = stem,
                .type = .Stem,
                .token_id = stem_id,
            });

            const suffix_id = self.token_to_id.get(suffix) orelse self.next_id + 1;
            try morphemes.append(.{
                .text = suffix,
                .type = .Suffix,
                .token_id = suffix_id,
            });

            found_suffix = true;
            break;
        }
    }

    if (!found_suffix and remaining.len > 0) {
        const token_id = self.token_to_id.get(remaining) orelse self.next_id;
        try morphemes.append(.{
            .text = remaining,
            .type = .Standalone,
            .token_id = token_id,
        });
    }

    return morphemes.toOwnedSlice();
}


