 Sequence Addition (Suffix Tree Build)
zig
pub fn addSequence(self: *SSI, tokens: []const u32, doc_id: u64, is_anchor: bool) !void {
    if (tokens.len == 0) return;

    for (0..tokens.len) |start_idx| {
        var current = self.root;

        for (tokens[start_idx..]) |token| {
            if (current.children.get(token)) |child| {
                current = child;
                current.frequency += 1;
            } else {
                const new_node = try SSINode.init(self.allocator, token);
                try current.children.put(token, new_node);
                current = new_node;
                self.node_count += 1;
            }
        }

        current.is_leaf = true;
        current.doc_id = doc_id;
        current.is_anchor = is_anchor;
        self.leaf_count += 1;
    }
}


