pub const Segment = struct {
    tokens: []u32,
    doc_id: u64,
    score: f32,
    is_anchor: bool,

    pub fn deinit(self: *Segment, allocator: Allocator) void {
        allocator.free(self.tokens);
    }
};

pub fn retrieveTopK(self: *SSI, query: []const u32, k: usize, allocator: Allocator) ![]Segment {
    var candidates = std.ArrayList(Segment).init(allocator);
    defer {
        for (candidates.items) |*seg| {
            if (candidates.items.len > k) seg.deinit(allocator);
        }
        candidates.deinit();
    }

    try self.collectCandidates(query, &candidates, allocator);

    for (candidates.items) |*candidate| {
        candidate.score = self.computeRelevance(query, candidate.tokens);
    }

    std.mem.sort(Segment, candidates.items, {}, struct {
        fn lessThan(_: void, a: Segment, b: Segment) bool {
            return a.score > b.score;
        }
    }.lessThan);

    const result_count = @min(k, candidates.items.len);
    const results = try allocator.alloc(Segment, result_count);

    for (0..result_count) |i| {
        results[i] = candidates.items[i];
    }

    return results;
}


Relevancia számítás:
zig
fn computeRelevance(self: *SSI, query: []const u32, candidate: []const u32) f32 {
    var overlap_count: usize = 0;

    for (query) |q_token| {
        for (candidate) |c_token| {
            if (q_token == c_token) {
                overlap_count += 1;
                break;
            }
        }
    }

    const query_len_f: f32 = @floatFromInt(query.len);
    const cand_len_f: f32 = @floatFromInt(candidate.len);
    const overlap_f: f32 = @floatFromInt(overlap_count);

    const jaccard = overlap_f / (query_len_f + cand_len_f - overlap_f);

    return jaccard;
}


