fn hashBigram(self: *Ranker, t1: u32, t2: u32) u64 {
    var hasher = std.hash.Wyhash.init(self.seed);
    hasher.update(std.mem.asBytes(&t1));
    hasher.update(std.mem.asBytes(&t2));
    return hasher.final();
}

fn hashTrigram(self: *Ranker, t1: u32, t2: u32, t3: u32) u64 {
    var hasher = std.hash.Wyhash.init(self.seed);
    hasher.update(std.mem.asBytes(&t1));
    hasher.update(std.mem.asBytes(&t2));
    hasher.update(std.mem.asBytes(&t3));
    return hasher.final();
}


