 Ranking Pipeline
zig
pub fn rankCandidates(self: *Ranker, candidates: []Segment, index: *SSI, allocator: Allocator) !void {
    for (candidates) |*candidate| {
        const ngram_score = self.computeNgramScore(candidate.tokens);
        const frequency_score = self.computeFrequencyScore(candidate.tokens, index);
        const anchor_boost: f32 = if (candidate.is_anchor) 1.5 else 1.0;

        candidate.score = (ngram_score * 0.4 + frequency_score * 0.6) * anchor_boost;
    }
}

fn computeFrequencyScore(self: *Ranker, tokens: []const u32, index: *SSI) f32 {
    var total_freq: usize = 0;

    for (tokens) |token| {
        if (index.root.children.get(token)) |node| {
            total_freq += node.frequency;
        }
    }

    const len_f: f32 = @floatFromInt(@max(tokens.len, 1));
    const freq_f: f32 = @floatFromInt(total_freq);
    const normalized = freq_f / len_f;

    return std.math.log10(1.0 + normalized);
}


