 Preferential Attachment (BarabásiAlbert)
zig
pub fn addNodeWithPreferentialAttachment(self: *SSRG, data: []const u8, embedding: []const f32, m: usize) !u64 {
    const new_node_id = try self.addNode(data, embedding);

    if (self.nodes.count() == 1) {
        return new_node_id;
    }

    var degrees = try self.allocator.alloc(usize, self.nodes.count() - 1);
    defer self.allocator.free(degrees);

    var node_ids = try self.allocator.alloc(u64, self.nodes.count() - 1);
    defer self.allocator.free(node_ids);

    var total_degree: usize = 0;
    var idx: usize = 0;
    var it = self.nodes.iterator();
    while (it.next()) |entry| {
        if (entry.key_ptr.* != new_node_id) {
            const degree = entry.value_ptr.*.edges.items.len;
            degrees[idx] = degree;
            node_ids[idx] = entry.key_ptr.*;
            total_degree += degree;
            idx += 1;
        }
    }

    if (total_degree == 0) {
        for (0..@min(m, node_ids.len)) |i| {
            _ = try self.addEdge(new_node_id, node_ids[i], 1.0, "preferential");
        }
        return new_node_id;
    }

    var connected = std.AutoHashMap(u64, void).init(self.allocator);
    defer connected.deinit();

    var prng = std.rand.DefaultPrng.init(@intCast(std.time.milliTimestamp()));
    const random = prng.random();

    while (connected.count() < @min(m, node_ids.len)) {
        const rand_val = random.uintLessThan(usize, total_degree);
        var cumulative: usize = 0;

        for (0..node_ids.len) |i| {
            cumulative += degrees[i];
            if (rand_val < cumulative and !connected.contains(node_ids[i])) {
                _ = try self.addEdge(new_node_id, node_ids[i], 1.0, "preferential");
                try connected.put(node_ids[i], {});
                break;
            }
        }
    }

    return new_node_id;
}


