zig
pub fn detectCommunities(self: *SSRG, allocator: Allocator) !std.AutoHashMap(u64, u64) {
    var communities = std.AutoHashMap(u64, u64).init(allocator);

    var it = self.nodes.keyIterator();
    while (it.next()) |node_id| {
        try communities.put(node_id.*, node_id.*);
    }

    var improved = true;
    var iteration: usize = 0;
    const MAX_ITERATIONS: usize = 100;

    while (improved and iteration < MAX_ITERATIONS) {
        improved = false;
        iteration += 1;

        var node_it = self.nodes.iterator();
        while (node_it.next()) |entry| {
            const node_id = entry.key_ptr.*;
            const current_community = communities.get(node_id).?;

            var neighbor_communities = std.AutoHashMap(u64, f32).init(allocator);
            defer neighbor_communities.deinit();

            for (entry.value_ptr.*.edges.items) |edge| {
                const neighbor_id = if (edge.source == node_id) edge.target else edge.source;
                const neighbor_community = communities.get(neighbor_id).?;

                const current_weight = neighbor_communities.get(neighbor_community) orelse 0.0;
                try neighbor_communities.put(neighbor_community, current_weight + edge.weight);
            }

            var best_community = current_community;
            var best_modularity: f32 = 0.0;

            var comm_it = neighbor_communities.iterator();
            while (comm_it.next()) |comm_entry| {
                const modularity = comm_entry.value_ptr.*;
                if (modularity > best_modularity) {
                    best_modularity = modularity;
                    best_community = comm_entry.key_ptr.*;
                }
            }

            if (best_community != current_community) {
                try communities.put(node_id, best_community);
                improved = true;
            }
        }
    }

    return communities;
}


