zig
pub fn trainStep(self: *DistributedTrainer, batch: []TrainingSample) !f32 {
    var total_loss: f64 = 0.0;

    for (batch) |sample| {
        const tensor_dim = std.math.mul(usize, self.local_model.dim, 2) catch continue;
        var input = try Tensor.init(self.allocator, &.{1, tensor_dim});
        defer input.deinit();

        try createEmbeddingInPlace(&input, sample.tokens, 1000, self.local_model.dim);

        try self.local_model.forward(&input);

        var sum: f64 = 0.0;
        for (input.data) |v| {
            if (!std.math.isNan(v) and !std.math.isInf(v)) {
                sum += @as(f64, v);
            }
        }
        const avg = sum / @as(f64, @floatFromInt(@max(input.data.len, 1)));
        total_loss += avg * avg;
    }

    try self.allReduceGradients();

    var gradients = try self.computeGradients();
    defer gradients.deinit();

    var params = try self.getFlattenedParams();
    defer params.deinit();

    try self.optimizer.update(&gradients, &params, 0.001);

    try self.applyFlattenedParams(&params);

    const batch_loss: f32 = @floatCast(total_loss / @as(f64, @floatFromInt(@max(batch.len, 1))));
    return batch_loss;
}


