pub const ContentAddressableStorage = struct {
    content_index: HashMap(ContentHash, BlockID),
    storage: HashMap(BlockID, []u8),

    pub fn store(self: *CAS, data: []const u8) !BlockID {
        const content_hash = computeContentHash(data);  // SHA256 -> Wyhash
        if (self.content_index.getPtr(content_hash)) |existing_id| {
            return existing_id.*;  // DEDUPLIKÁCIÓ
        }
        const new_id = self.allocateNewBlock();
        try self.storage.put(new_id, try self.allocator.dupe(u8, data));
        try self.content_index.put(content_hash, new_id);
        return new_id;
    }
};


