pub const DynamicTaskScheduler = struct {
    cores: []ProcessingCore,
    data_dependencies: HashMap(TaskID, []BlockID),

    pub fn scheduleTask(self: *Scheduler, task: Task) !void {
        const nearest_core = self.findNearestCore(task.required_blocks);
        try self.assignToCore(task, nearest_core);
    }

    fn findNearestCore(self: *Scheduler, blocks: []BlockID) CoreID {
        var best_core: CoreID = 0;
        var min_distance: f32 = std.math.inf(f32);

        for (self.cores, 0..) |core, i| {
            const distance = self.computeDataDistance(core, blocks);
            if (distance < min_distance) {
                min_distance = distance;
                best_core = @intCast(i);
            }
        }
        return best_core;
    }
};


