pub fn buildFlowGraph(self: *ChaosCore) !void {
    var flow_counts = std.AutoHashMap(FlowEdge, usize).init(self.allocator);
    defer flow_counts.deinit();

    for (self.task_history.items) |task| {
        for (task.inputs) |input_block| {
            for (task.outputs) |output_block| {
                const edge = FlowEdge{ .from = input_block, .to = output_block };
                const count = flow_counts.get(edge) orelse 0;
                try flow_counts.put(edge, count + 1);
            }
        }
    }

    self.flow_graph = try self.convertToWeightedGraph(flow_counts);
}


