 B. Kauzális Visszakövetés (Invertálhatóság)

processor/rsf.zig inverse metódus:
zig
pub fn inverse(self: *RSF, output: *Tensor) !void {
    var layer_idx: usize = self.num_layers;
    while (layer_idx > 0) {
        layer_idx -= 1;
        const layer = &self.layers[layer_idx];

        // Defúzió (relational fusion visszafordítása)
        try relationalDefusion(output, self.dim);

        // SiLU inverz (numerikus megoldás)
        var s_part = try output.slice(&.{0, 0}, &.{batch, self.dim});
        defer s_part.deinit();
        try s_part.apply(silu_inverse);  // Newton-módszer

        // Affin transzformáció inverz
        try s_part.sub(&layer.s_bias);
        var s_weight_inv = try layer.s_weight.pseudoinverse();  // SVD
        defer s_weight_inv.deinit();
        var s_inv = try s_part.matmul(&s_weight_inv);
        defer s_inv.deinit();

        @memcpy(output.data[0..batch * self.dim], s_inv.data);
    }
}


